async (el) => {
  const html = document.documentElement;
  const prevBehavior = html.style.scrollBehavior;
  html.style.scrollBehavior = 'auto';

  const bar = document.querySelector('.topbar');
  const links = [...document.querySelectorAll('.topbar nav a[href^="#"]')];
  const sections = links.map((a) => document.querySelector(a.getAttribute('href')));
  const frame = () => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));

  const violations = [];
  const noneActive = [];
  const trace = [];
  const max = html.scrollHeight - innerHeight;
  const STEPS = 120;

  for (let i = 0; i <= STEPS; i++) {
    const y = Math.round((max * i) / STEPS);
    scrollTo(0, y);
    await frame();

    const barBottom = bar.getBoundingClientRect().bottom;
    const activeLink = links.find((a) => a.getAttribute('aria-current') === 'true');
    const activeId = activeLink ? activeLink.getAttribute('href').slice(1) : null;
    const idx = activeId ? sections.findIndex((s) => s.id === activeId) : -1;

    if (idx === -1) { noneActive.push(y); continue; }

    // RULE: nothing before the active section may still be showing below the bar.
    for (let j = 0; j < idx; j++) {
      const r = sections[j].getBoundingClientRect();
      const stillShowing = Math.round(r.bottom - barBottom);
      if (stillShowing > 1) {
        violations.push({ y, active: activeId, leftover: sections[j].id, px: stillShowing });
      }
    }

    // The active section should itself be on screen (not already scrolled past).
    const ar = sections[idx].getBoundingClientRect();
    const atBottom = scrollY + innerHeight >= html.scrollHeight - 2;
    if (!atBottom && (ar.bottom <= barBottom || ar.top >= innerHeight)) {
      violations.push({ y, active: activeId, leftover: 'ACTIVE_OFFSCREEN', px: Math.round(ar.bottom - barBottom) });
    }

    trace.push({ y, active: activeId });
  }

  html.style.scrollBehavior = prevBehavior;
  scrollTo(0, 0);

  // Collapse the trace into the scroll ranges each link owns.
  const ranges = [];
  for (const t of trace) {
    const last = ranges[ranges.length - 1];
    if (last && last.id === t.active) last.to = t.y;
    else ranges.push({ id: t.active, from: t.y, to: t.y });
  }

  return JSON.stringify({
    scrollHeight: html.scrollHeight,
    viewport: innerHeight,
    samples: STEPS + 1,
    violations: violations.length,
    firstViolations: violations.slice(0, 8),
    noneActiveAt: noneActive.slice(0, 5),
    ranges,
  }, null, 1);
}

