.toc a.g-assets       { border-left-color: var(--lime); }
.toc a.g-assets .n    { color: var(--lime); }
.toc a.g-rules        { border-left-color: var(--violet); }
.toc a.g-rules .n     { color: var(--violet); }
.toc a:hover .n       { color: var(--bright-green); }

/* Quoted vocabulary in the voice table. Prefer terms use the token code chip;
   avoid terms keep the same shape with a Hot Red fill so the pair reads as a
   pair. Words stay in the foreground where Hot Red would fail the floor. */
.term {
  font-family: var(--font-mono); font-size: 0.92em;
  padding: 2px 6px; border-radius: var(--r-1);
  background: rgba(137,223,0,0.12); color: var(--bright-green);
  border: 1px solid rgba(137,223,0,0.22);
  white-space: nowrap;
}
.term.avoid {
  background: rgba(230,57,70,0.14); color: var(--fg);
  border-color: rgba(230,57,70,0.35);
}

