cd /home/damien/Liatrio/repos/ai-prompts && playwright-cli eval "() => {
  const srgb = c => { c/=255; return c<=0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4); };
  const lum = ([r,g,b]) => 0.2126*srgb(r)+0.7152*srgb(g)+0.0722*srgb(b);
  const parse = s => { const m=(s||'').match(/[\\d.]+/g); return m ? m.slice(0,4).map(Number) : null; };
  const over = (fg,bg) => { const a=fg[3]===undefined?1:fg[3]; return [0,1,2].map(i=>fg[i]*a+bg[i]*(1-a)); };
  const ratio = (a,b) => { const l1=lum(a),l2=lum(b); return +((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2); };
  const samples = [...document.querySelectorAll('.term')].slice(0,8).map(el => {
    const cs = getComputedStyle(el);
    const fg = parse(cs.color);
    let n=el, stack=[];
    while(n && n.nodeType===1){ const c=parse(getComputedStyle(n).backgroundColor); if(c && (c[3]===undefined||c[3]>0)) stack.push(c); n=n.parentElement; }
    let base=[26,31,35];
    for(let i=stack.length-1;i>=0;i--) base=over(stack[i], base);
    return { text: el.textContent, cls: el.className, color: cs.color, bg: cs.backgroundColor, ratio: ratio(over(fg,base), base) };
  });
  return JSON.stringify(samples, null, 2);
}" "body" --filename /tmp/term-contrast.json 2>&1 | tail -1 && uv run python -c "import json; print(json.loads(json.loads(open('/tmp/term-contrast.json').read())))"
